"""Regenerate browser and packaged prompt copies from the public Markdown.

The page shows and copies the prompt from prompt.js (so it works from disk, where
fetch() is blocked); the .md file is what visitors download. Run after editing the .md:
    python3 site/tools/sync_prompt.py
"""
import json
from pathlib import Path

assets = Path(__file__).resolve().parent.parent / "assets"
text = (assets / "connect-the-bots-prompt.md").read_text(encoding="utf-8")
(assets / "prompt.js").write_text(
    "// Generated by site/tools/sync_prompt.py from connect-the-bots-prompt.md. Do not edit.\n"
    "window.CTB_PROMPT = " + json.dumps(text, ensure_ascii=False) + ";\n",
    encoding="utf-8",
)
print("wrote", assets / "prompt.js")

packaged = assets.parents[1] / "src" / "connectthebots_server" / "prompt.py"
source = packaged.read_text(encoding="utf-8")
begin = "# BEGIN GENERATED PUBLIC PROMPT\n"
end = "# END GENERATED PUBLIC PROMPT"
if source.count(begin) != 1 or source.count(end) != 1:
    raise ValueError("Packaged prompt markers are missing or duplicated")
before, remainder = source.split(begin, 1)
_, after = remainder.split(end, 1)
packaged.write_text(before + begin + "PUBLIC_PROMPT = " + repr(text) + "\n" + end + after, encoding="utf-8")
print("wrote", packaged)
